import java.io.BufferedReader
import java.io.InputStreamReader
import java.io.PrintWriter
import java.util.*

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val pw = PrintWriter(System.out)
    val st = StringTokenizer(br.readLine())
    val n = st.nextToken().toInt()
    val m = st.nextToken().toInt()
    val q = st.nextToken().toInt()

    val p = IntArray(n + 1)
    val pos = IntArray(n + 1)
    val st2 = StringTokenizer(br.readLine())
    for (i in 1..n) {
        p[i] = st2.nextToken().toInt()
        pos[p[i]] = i
    }

    val edges = Array(m + 1) { IntArray(2) }
    val deleted = BooleanArray(m + 1)
    for (i in 1..m) {
        val stE = StringTokenizer(br.readLine())
        edges[i][0] = stE.nextToken().toInt()
        edges[i][1] = stE.nextToken().toInt()
    }

    val queries = Array(q) { IntArray(2) }
    for (i in 0 until q) {
        val stQ = StringTokenizer(br.readLine())
        val t = stQ.nextToken().toInt()
        val x = stQ.nextToken().toInt()
        queries[i][0] = t
        queries[i][1] = x
        if (t == 2) {
            deleted[x] = true
        }
    }

    val dsu = DSU(n)
    for (i in 1..m) {
        if (!deleted[i]) {
            dsu.union(edges[i][0], edges[i][1])
        }
    }

    val compMax = IntArray(n + 1)
    for (i in 1..n) {
        compMax[i] = p[i]
    }

    val ans = mutableListOf<Int>()

    for (i in q - 1 downTo 0) {
        val t = queries[i][0]
        val x = queries[i][1]
        if (t == 1) {
            val root = dsu.find(x)
            val mx = compMax[root]
            ans.add(mx)
            if (mx != 0) {
                val u = pos[mx]
                compMax[root] = 0
            }
        } else {
            val u = edges[x][0]
            val v = edges[x][1]
            dsu.union(u, v)
        }
    }

    for (i in ans.lastIndex downTo 0) {
        pw.println(ans[i])
    }
    pw.flush()
}

class DSU(n: Int) {
    val parent = IntArray(n + 1) { it }
    val rank = IntArray(n + 1)

    fun find(x: Int): Int {
        if (parent[x] != x) {
            parent[x] = find(parent[x])
        }
        return parent[x]
    }

    fun union(a: Int, b: Int) {
        var ra = find(a)
        var rb = find(b)
        if (ra == rb) return
        if (rank[ra] < rank[rb]) {
            val tmp = ra
            ra = rb
            rb = tmp
        }
        parent[rb] = ra
        if (rank[ra] == rank[rb]) rank[ra]++
    }
}
